from lib import *
S = SS('h20')
steps = [
    step("grpc.health.v1 的 Check:新建的 health.Server 对服务名“”(整体)返回 SERVING;对没登记的服务名 demo.Demo,RPC 本身失败:NotFound“unknown service”;SetServingStatus 设成 NOT_SERVING 后,RPC 是成功的,响应里的 status 字段是 NOT_SERVING(不是 RPC 错误);再设回 SERVING 则恢复。List 返回所有登记的服务:“”:SERVING 和 “demo.Demo”:SERVING。所以判断健康要看响应里的 status,而不是只看 RPC 有没有成功。", t=tl(S(1)), done=lidx(S(1), 'List:'), mark=lidx(S(1), '没登记'), b=bars([['没登记的服务名:Check 的 RPC 是否失败(1=失败)', 1, 'NotFound'], ['登记为 NOT_SERVING:RPC 是否失败(0=成功)', 0, '成功,status=NOT_SERVING']], 1.2, mark=[0], done=[1]), kv=KV([['服务名 “”', 'SERVING(默认)'], ['没登记', 'RPC 失败 NotFound'], ['NOT_SERVING', 'RPC 成功,status=NOT_SERVING']], ['NOT_SERVING'])),
    step("Watch(流式的健康检查):对没登记的服务名 svc,刚开始立刻收到一条 SERVICE_UNKNOWN(没有像 Check 那样报 NotFound);设成 SERVING 后收到 [SERVING];再连续设置 2 次 SERVING 什么都没收到(状态没变不发);设为 NOT_SERVING 收到 [NOT_SERVING]。状态变化到客户端收到的延迟 0.2 ms。紧接着快速交替设置 1000 次,客户端只收到 14 条,最后一条是 SERVING——服务端只保留“最新的状态”,中间的变化会被合并(读源码:setServingStatusLocked 会清掉还没发出去的旧状态),所以 Watch 能可靠地给出最终状态,但不保证看到每一次变化。", t=tl(S(2)), done=lidx(S(2), '紧接着快速交替'), mark=lidx(S(2), 'Watch("svc") 刚开始'), b=bars([['服务端设置状态的次数', 1000, '1000'], ['客户端收到的条数', 14, '14']], 1050, mark=[0], done=[1]), kv=KV([['没登记的服务', '先收到 SERVICE_UNKNOWN'], ['重复设置同一状态', '不发'], ['快速翻转 1000 次', '客户端收到 14 条,最终状态正确']], ['快速翻转 1000 次'])),
    step("Shutdown / Resume:服务端准备退出时调用 Shutdown(),所有服务(包括“”和 svc)立刻变成 NOT_SERVING;此后的 SetServingStatus(svc, SERVING) 被忽略,svc 仍是 NOT_SERVING(防止别的 goroutine 又把它设回去);Resume() 后恢复成 SERVING 并重新接受修改。优雅停机的顺序通常是:先 Shutdown 让负载均衡器把它摘掉,再 GracefulStop(第 34 篇)。", t=tl(S(3)), done=lidx(S(3), 'Resume 之后'), mark=lidx(S(3), 'Shutdown 之后:'), b=bars([['Shutdown 之后 “”', 0, 'NOT_SERVING'], ['再 SetServingStatus 之后 svc', 0, 'NOT_SERVING(被忽略)'], ['Resume 之后', 1, 'SERVING']], 1.3, mark=[0, 1], done=[2]), kv=KV([['Shutdown()', '所有服务 NOT_SERVING'], ['之后的 Set', '被忽略'], ['Resume()', '恢复 SERVING,重新接受修改']], ['之后的 Set'])),
    step("客户端健康检查:3 个后端 + round_robin,把后端 1 设为 NOT_SERVING。不配置 healthCheckConfig:60 次调用各后端 [20 20 20],设置之后 1.5 秒内一直打到后端 1(最后一次在 1491.5 ms),之后 60 次还是 [20 20 20]——健康服务对客户端没有影响。服务配置里加 healthCheckConfig {serviceName: \"\"}:后端 1 最后一次被打到是设置之后 0.1 ms,之后 60 次变成 [30 0 30],后端 1 被从轮询里摘掉(连接还在)。3 个后端全部 NOT_SERVING 后调用得到 Unavailable“pickfirst: health check failure: connection active but health check failed. status=NOT_SERVING”;后端 2 恢复 SERVING 后调用成功。注意:客户端只有在服务配置里启用了 healthCheckConfig 才会去调用健康检查服务。", t=tl(S(4)), done=lidx(S(4), '后端 2 恢复'), mark=lidx(S(4), '有 healthCheckConfig:后端 1 设为'), b=bars([['无 healthCheckConfig:后端 1 在设置后收到(60 次里)', 20, '20'], ['有 healthCheckConfig:后端 1 在设置后收到(60 次里)', 0, '0']], 22, mark=[0], done=[1]), kv=KV([['无 healthCheckConfig', '[20 20 20],健康状态被忽略'], ['有 healthCheckConfig', '[30 0 30],摘掉 NOT_SERVING 的后端'], ['全部 NOT_SERVING', 'Unavailable: health check failure']], ['有 healthCheckConfig'])),
]
A = mkarth('h20', 20, 'gRPC,健康检查,grpc.health.v1,Watch,Shutdown,healthCheckConfig,Go,真实验证,动画演示',
    '实测 grpc.health.v1:Check 对没登记的服务返回 NotFound、NOT_SERVING 是成功的响应;Watch 对没登记的服务先给 SERVICE_UNKNOWN、快速变化会被合并;Shutdown 之后设置被忽略;客户端要配置 healthCheckConfig 才会摘掉不健康的后端。',
    'gRPC 官方的健康检查协议怎么用?Check 和 Watch 的行为有什么不同?服务关闭时怎么表示?客户端怎么才会真的避开不健康的后端?这篇逐项验证。',
    [('NotFound vs 成功', 'Check 对没登记的服务返回 NotFound;登记为 NOT_SERVING 时 RPC 成功、status 为 NOT_SERVING'), ('1000 次 → 14 条', '快速翻转 1000 次状态,Watch 客户端实际收到的条数(最终状态正确)'), ('[20 20 20] → [30 0 30]', '后端 1 设为 NOT_SERVING 后,60 次调用分布(无 / 有 healthCheckConfig)')],
    [('协议', '<p>grpc.health.v1.Health 有 Check(一次性)、Watch(流式推送状态变化)、List。服务名为空字符串表示整个服务器的整体状态。health.Server 是官方实现,用 SetServingStatus 修改状态。</p>'),
     ('Watch 的语义', '<p>没登记的服务先返回 SERVICE_UNKNOWN;状态没变化不重复发;变化太快时中间状态会被合并,保证最后收到的是最新状态。</p>'),
     ('Shutdown', '<p>Shutdown() 把所有服务设为 NOT_SERVING 并忽略之后的修改,Resume() 恢复。适合在停机前先让上游摘除自己。</p>'),
     ('客户端怎么用', '<p>客户端只有在服务配置里设置了 healthCheckConfig,才会对每个连接发起 Watch,并避开 NOT_SERVING 的后端。没有这个配置,健康状态不影响负载均衡。</p>')],
    steps,
    [ENV_H + '。健康服务用 google.golang.org/grpc/health(官方实现);“快速翻转”的条数每次运行不同(两次运行分别是 8 和 14);时间差用 handler 与客户端本地的时钟测;“合并旧状态”“Shutdown 之后忽略”读自 health/server.go;客户端健康检查需要服务配置里的 healthCheckConfig,并导入 google.golang.org/grpc/health 以注册客户端检查',
     '没有验证:grpc_health_probe 等外部工具;Kubernetes 的原生 gRPC 探针;healthCheckConfig 指定非空服务名时的行为;health 检查本身失败(例如服务端没有实现 health 服务)时客户端的行为;大量后端时每个连接一个 Watch 的开销'],
    '健康检查')
